source.loginJs:
// 当前书源版本号，切勿修改，否则影
let localVersion = '4.7.09';

function login(flag) {
	if (flag == undefined) {
		result = JSON.parse(source.getLoginInfo())
	} else {
		putLoginInfo(JSON.stringify(result))
	}
	let base_url = getArgument('server')
	let zdyserver = String(result['自定义服务器(可不填)']);
	if (zdyserver.includes('http')) {
		setArgument('server', zdyserver);
		if (cookie.getKey(base_url,"qttoken")){
			let cookies=cookie.getCookie(base_url)
			removeCookie(base_url)
			cookie.setCookie(zdyserver,cookies)
		}
		java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
	}
	let zdytone_id = String(result['听书Ai音色填写后点击右上角✔'] || '');
	if (zdytone_id) {
		setArgument('tone_id', zdytone_id);
	} else {
		setArgument('tone_id', '默认音色');
	}

	let sq_user_id = String(result['书旗id(可不填)'] || '');
	if (sq_user_id) {
		setArgument('sq_user_id', sq_user_id);
	} else {
		setArgument('sq_user_id', '0');
	}
	base_url = getArgument('server')
	let register_email = String(result['邮箱'])
	let password = String(result['密码'])
	let key = String(result['密钥'])

	//java.log(cookie.getCookie(base_url))
	if ((register_email && password || key)&& !String(cookie.getKey(base_url,"qttoken"))) {
		removeCookie(base_url)
		let deviceKey = java.webView('', '', 'navigator.userAgent+window.screen.width+window.screen.height')
		let deviceId = java.digestHex(deviceKey, "SHA256")
		java.longToast("正在登录中...")
		if (register_email && password){
			let options = JSON.stringify({
				method: 'POST',
				headers: {
					'Content-Type': 'application/json'
				},
				body: JSON.stringify({
					register_email: result['邮箱'],
					password: result['密码']
				})
			})
			try {
				let data = JSON.parse(java.ajax(`${base_url}/login_api,${options}`))
				if (data.code == 0) {
					java.toast("登录成功")
					cookie.setCookie(base_url, `qttoken=${data.key};deviceId=${deviceId}`)
					result['密钥']=data.key
					putLoginInfo(JSON.stringify(result))
				} else {
					java.toast(data.msg || "登录失败，请重试！")
				}
			} catch (e) {
				java.toast("登录失败，请重试！\n" + e.message)
			}
		} else {
			cookie.setCookie(base_url, `qttoken=${key};deviceId=${deviceId}`)
			let res=java.ajax(`${base_url}/user_api,{"method":"POST"}`)
			try {
				res=JSON.parse(res)
				if (res.id!=undefined) {
					java.toast('密钥登录成功')
					result['邮箱'] = res.email
					putLoginInfo(JSON.stringify(result))
				} else {
					throw new Error()
				}
			} catch(e) {
				java.log(e)
				java.toast("登录失败")
			}
		}
	} else if (flag&&String(cookie.getKey(base_url,"qttoken"))) {
		java.toast("当前已登录，请退出登录后重新登录")
	}
}

function checkStatus() {
	let base_url = getArgument('server')
	let res=java.ajax(`${base_url}/user_api,{"method":"POST"}`)
	try {
				res=JSON.parse(res)
				if (res.id!=undefined) {
					result['邮箱'] = res.email
					putLoginInfo(JSON.stringify(result))
					let devices
					try {
						devices = JSON.parse(res.device).length;
					} catch (e) {
						devices = res.device ? 1 : 0;
					}
					let isVip;
					if (res.is_vip==1) {
						isVip = 'VIP';
					} else if (res.is_vip>=2) {
						isVip = 'SVIP';
					} else {
						isVip = '普通会员';
					}
					tips= `
┏┅┅┅┅┅┅┱┄┄┄┄┄┄┄┄┄┄┐
　✉️邮箱　　　　${res.email.replace(/(.{3}).*?@/,"$1***@").padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🔑密钥　　　　${(`${res.user_key.substring(0,4)}***${res.user_key.slice(-4)}`).padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📅注册时间　　${java.timeFormat(res.register_time*1000).padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🗒️今日阅读　　${(java.timeFormat(new Date()).slice(0,10)==java.timeFormat(res.last_read_time * 1000).slice(0,10)?res.day_read_count:0).toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📚累计阅读　　${res.all_read_count.toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🕓最后阅读　　${(res.last_read_time != 0?java.timeFormat(res.last_read_time * 1000):'未阅读').padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　📱关联设备　　${devices.toString().padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　👑会员状态　　${isVip.padEnd(20,"\t")}
┣┅┅┅┅┅┅╉┄┄┄┄┄┄┄┄┄┄┤
　🚫封禁状态　　${res.is_banned?'已封禁':'正常　'}　　　　　　　
┗┅┅┅┅┅┅┹┄┄┄┄┄┄┄┄┄┄┘
`
					java.log(tips)
					java.longToast(tips)
				} else {
					throw new Error(res.msg)
				}
			} catch(e) {
				//java.log(e)
				java.toast("\n检测登录失败\n"+e.message)
			}
}

function clearDevice() {
	let base_url = getArgument('server')
	let res=JSON.parse(java.ajax(`${base_url}/clear,{"method":"POST"}`))
	java.toast(res.code === 0 ? "设备清除成功" : res.msg)
	Packages.java.lang.Thread.sleep(500)
	checkStatus()
}

function qtsj() {
	java.startBrowserAwait(getArgument('server') + '/online_bookshelf', '大灰狼书架');
}

// 填写密钥
function loginqt() {
	java.startBrowserAwait(getArgument('server') + '/login', '登录大灰狼小说书源');
}

//登录番茄
function fq_login() {
	try {
		java.startBrowserAwait("https://fanqienovel.com/", "登录")
	} catch (e) {
		java.toast(e)
	}
	try {
		cookie.removeCookie("snssdk.com")
	} catch (e) {}
	var cookies = cookie.getCookie("fanqienovel.com")
	if (!cookies || cookies == "") {
		java.toast("登录失败！")
		return false
	}
	java.toast("登录成功！")
	return true
}

//退出登录
function logout() {
	cookie.removeCookie("fanqienovel.com");
	cookie.removeCookie("snssdk.com");
	/*
	let servers = host
	for (let server of servers) {
		removeCookie(server);
	}
	*/
	removeCookie(getArgument('server'))
	java.toast("退出登录成功");
}

//获取参数
function getArgument(key) {
	let open_argument = source.getVariable();
	open_argument = getArguments(open_argument, '');
	return open_argument[key];
}

// 保存登录UI信息
function putLoginInfo(info) {
	try {
		let key = java.androidId()
		let encodeStr = Packages.android.util.Base64.encodeToString(java.createSymmetricCrypto("AES", key).encrypt(info), 2)
		cache.put(`userInfo_${source.getKey()}`, encodeStr)
		return true
	} catch (e) {
		java.log(e)
		return source.putLoginInfo(info)
	}
}

//设置参数
function setArgument(key, value) {
	let open_argument = source.getVariable();
	open_argument = getArguments(open_argument, '');
	open_argument[key] = value;
	open_argument = JSON.stringify(open_argument);
	source.setVariable(open_argument);
	return open_argument;
}

//设置男女频
function set_source_type(source_type) {
	setArgument("source_type", source_type);
	java.toast("\n发现页已设置为:" + source_type);
}

//首页
