var server = getArgument('server');

//设置搜索媒体
function set_media(media) {
	const mediaConfig = {
		'喜马拉雅': ['听书'],
		'番茄': '*',
		'福利小说': ['小说'],
		'如漫画': ['漫画'],
		'包子漫画': ['漫画'],
		'九妖漫画': ['漫画'],
		'绅士漫画': ['漫画'],
		'福利漫画': ['漫画'],
		'海洋听书': ['听书'],
		'酷狗听书': ['听书'],
		'七猫': ['小说', '听书'],
		'河马': ['短剧'],
		'歪瑞古德': ['漫画'],
		'毒舌影视': ['短剧'],
		'全部': '*', // 允许所有模式
		'默认': ['小说']
	};

	const source = getArgument('source');
	const allowedModes = mediaConfig[source] || mediaConfig['默认'];
	let targetMedia = mediaConfig['默认'][0];
	let isAllowed = false;

	if (allowedModes === '*' || allowedModes.includes(media)) {
		targetMedia = media;
		isAllowed = true;
	} else if (Array.isArray(allowedModes)) {
		targetMedia = allowedModes[0];
	}

	const message = isAllowed ?
		`\n\n已切换至：${targetMedia}\n请重新搜索书籍！` :
		`\n\n目前${source}：不支持【${media}】模式！\n已自动切换至：${targetMedia}`;

	setArgument('media', targetMedia);
	java.toast(message);
}

//获取搜索媒体
function get_media() {
	let media = getArgument('media');
	let source = getArgument('source');
	if (media == '') {
		media = '全部';
	}
	java.toast(`\n\n当前使用源：${source}-${media}`);

}

//获取服务器
function get_server() {
	var server = getArgument('server');
	var tishi = '\n\n当前服务器：' + server
	java.toast(tishi);
	return server
}


//设置服务器
function set_server() {
	putLoginInfo(JSON.stringify(result))
	let zdyserver;
	let base_url = getArgument('server')
	try {
		zdyserver = String(result['自定义服务器(可不填)']);
		if (zdyserver.includes('http')) {
			setArgument('server', zdyserver);
			if (cookie.getKey(base_url,"qttoken")){
				let cookies=cookie.getCookie(base_url)
				removeCookie(base_url)
				cookie.setCookie(zdyserver,cookies)
			}
			java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
		} else {
			zdyserver = '';
		}
	} catch (error) {
		zdyserver = '';
	}
	if (!zdyserver) {
		const servers = host
		const currentServer = getArgument('server') || '';
		const currentIndex = servers.indexOf(currentServer);

		const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % servers.length : 0;
		const nextServer = servers[nextIndex];

		setArgument('server', nextServer);
		if (cookie.getKey(currentServer,"qttoken")){
			let cookies=cookie.getCookie(currentServer)
			removeCookie(currentServer)
			cookie.setCookie(nextServer,cookies)
		}
		java.toast(`\n\n当前服务器${nextIndex+1}:${nextServer}\n\n注意：切换服务器后需要在详情页刷新目录才能生效`);
	}
}

//获取音色
var tone_id = getArgument('tone_id');

function get_tone_id(arg) {
	var datadist = {
		"0": "默认音色",
		"-1": "阅读模式",
		"-2": "漫画模式",
		"51": "多人发音",
		"1": "甜美少女",
		"2": "清亮青叔",
		"5": "开朗青年",
		"6": "温柔淑女",
		"4": "成熟大叔",
		"74": "大叔升级",
		"30": "优雅御姐"
	};
	var tone_id = datadist[arg] || arg;
	var tishi = '\n\n当前音色：' + tone_id;
	java.toast(tishi);
}

//设置音色
function set_tone_id(mode, name) {
	putLoginInfo(JSON.stringify(result))
	let zdytone_id;
	try {
		zdytone_id = String(result['其他音色填写后点击右上角✔']);
		if (zdytone_id) {
			setArgument('tone_id', zdytone_id);
			java.toast(`\n\n当前音色为自定义音色\n${zdytone_id}\n\n切换音色请先清空音色输入框中的数据`);
		} else {
			zdytone_id = '';
		}
	} catch (error) {
		zdytone_id = '';
	}
	if (!zdytone_id) {
		let toast = "\n\n已切换至：" + name + '\n\n切换后需要刷新详情页';
		setArgument('tone_id', mode);
		java.toast(toast);
	}
}

//设置来源
function set_source(source) {
	setArgument('source', source);
	set_media('小说');
	java.toast(`\n\n当前来源已切换为:\n${source}\n\n切换后请重新搜索`);
}


// 番茄段评
function paracomment(a) {
	let status = cache.get(a);
	if (status == "on") {
		cache.put(a, "off");
		java.toast("\n段评已关闭");
	} else {
		cache.put(a, "on");
		java.longToast("段评已开启\n\n长按刷新段后面的图片即可\n\n如果图片不显示，刷新无反应\n请更新测试版阅读app");
	}
} // 书源更新
